/**
 * Patches the generated Prisma client so the query-compiler wasm module can
 * be injected instead of compiled at runtime.
 *
 * prisma/generated/ is regenerated by `prisma generate`, so this patch must
 * be re-applied after every generate (chained into postinstall and
 * cloudflare:build; it is idempotent). The patch adds a globalThis check at
 * the top of `config.compilerWasm.getQueryCompilerWasmModule` in
 * prisma/generated/prisma/internal/class.ts — when worker.ts has injected a
 * statically-bound WebAssembly.Module (the only workerd-legal form) it is
 * returned directly; otherwise the original base64 path runs unchanged
 * (Node/Bun dev keep working exactly as before).
 *
 * With --strip-fallback (chained into cloudflare:build only) the base64
 * fallback import is REPLACED by a throw: the deployed worker always has the
 * injected module, and dropping the import keeps the ~6.3 MB base64 blob out
 * of the bundle entirely — a 25 MB handler spends cold-start budget on
 * parsing and can trip workerd's startup watchdog on loaded hosts (observed
 * as nondeterministic "hung" isolates on a subset of cold starts).
 *
 * Run: bun run prisma-wasm:prepare (also chained into postinstall)
 */
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const STRIP_FALLBACK = process.argv.includes('--strip-fallback');

const TARGET = path.join(
  process.cwd(),
  'prisma/generated/prisma/internal/class.ts',
);

const ANCHOR =
  'getQueryCompilerWasmModule: async () => {\n    const { wasm } = await import("@prisma/client/runtime/query_compiler_fast_bg.postgresql.wasm-base64.mjs")';

const INJECTED = `getQueryCompilerWasmModule: async () => {
    // Injected by scripts/patch-prisma-wasm.ts: on Cloudflare Workers the
    // statically-bound module from worker.ts (globalThis) is used because
    // workerd forbids compiling wasm bytes at runtime.
    const injected = (globalThis as { __OT_PRISMA_QUERY_COMPILER_WASM__?: WebAssembly.Module }).__OT_PRISMA_QUERY_COMPILER_WASM__;
    if (injected != null) return injected;
    const { wasm } = await import("@prisma/client/runtime/query_compiler_fast_bg.postgresql.wasm-base64.mjs")`;

const MARKER = '__OT_PRISMA_QUERY_COMPILER_WASM__';

let source: string;
try {
  source = readFileSync(TARGET, 'utf8');
} catch (error) {
  console.error(`cannot read ${TARGET} — run \`prisma generate\` first: ${error}`);
  process.exit(1);
}

// Each patch below is independent: an already-applied patch must not stop
// the others from being checked (they may be newly added or freshly
// regenerated), so none of the "already patched" branches exit early.
const FALLBACK_IMPORT =
  'const { wasm } = await import("@prisma/client/runtime/query_compiler_fast_bg.postgresql.wasm-base64.mjs")';

if (STRIP_FALLBACK) {
  // The prepare patch (or a prior generate) left the fallback import in
  // place — replace it so bundlers never inline the base64 module. Only the
  // deploy pipeline runs this mode; the worker always injects the module.
  if (source.includes('wasm module binding is required on this build')) {
    console.log('prisma base64 fallback already stripped — nothing to do');
  } else if (source.includes(FALLBACK_IMPORT)) {
    source = source.replace(
      FALLBACK_IMPORT,
      'throw new Error("Prisma query compiler wasm module binding is required on this build — run via worker.ts")',
    );
    writeFileSync(TARGET, source);
    console.log(
      `stripped base64 fallback from ${path.relative(process.cwd(), TARGET)}`,
    );
  } else {
    console.error(
      'expected fallback import not found in generated class.ts — Prisma version changed; update scripts/patch-prisma-wasm.ts',
    );
    process.exit(1);
  }
} else if (source.includes(MARKER)) {
  console.log('prisma client already patched — nothing to do');
} else if (!source.includes(ANCHOR)) {
  console.error(
    'expected loader shape not found in generated class.ts — the Prisma version changed; update scripts/patch-prisma-wasm.ts',
  );
  process.exit(1);
} else {
  source = source.replace(ANCHOR, INJECTED);
  writeFileSync(TARGET, source);
  console.log(`patched ${path.relative(process.cwd(), TARGET)}`);
}

/**
 * pg's stream resolver (node_modules/pg/lib/stream.js) switches to the
 * pg-cloudflare socket adapter when it detects the Cloudflare runtime. Under
 * OpenNext, pg-cloudflare's exports map resolves to an empty stub for
 * non-workerd-aware bundlers, yielding "CloudflareSocket is not a
 * constructor". Modern workerd (nodejs_compat, compat date 2025-04-01)
 * supports node:net/node:tls TCP directly — Cloudflare's own Postgres
 * tutorial uses plain pg this way with Hyperdrive — so force the Node stream
 * path unconditionally.
 */
const PG_STREAM = path.join(process.cwd(), 'node_modules/pg/lib/stream.js');
const PG_ANCHOR = `function getStreamFuncs() {
  if (isCloudflareRuntime()) {
    return getCloudflareStreamFuncs()
  }
  return getNodejsStreamFuncs()
}`;
const PG_REPLACEMENT = `function getStreamFuncs() {
  // Patched by scripts/patch-prisma-wasm.ts: workerd supports node:net TCP
  // under nodejs_compat, and pg-cloudflare resolves to an empty stub when
  // bundled for OpenNext — always use the Node stream implementation.
  return getNodejsStreamFuncs()
}`;

let pgSource: string;
try {
  pgSource = readFileSync(PG_STREAM, 'utf8');
} catch (error) {
  console.error(`cannot read ${PG_STREAM}: ${error}`);
  process.exit(1);
}

if (pgSource.includes('Patched by scripts/patch-prisma-wasm.ts')) {
  console.log('pg stream resolver already patched — nothing to do');
} else if (!pgSource.includes(PG_ANCHOR)) {
  console.error(
    'expected stream.js shape not found in node_modules/pg — pg version changed; update scripts/patch-prisma-wasm.ts',
  );
  process.exit(1);
} else {
  writeFileSync(PG_STREAM, pgSource.replace(PG_ANCHOR, PG_REPLACEMENT));
  console.log(`patched ${path.relative(process.cwd(), PG_STREAM)}`);
}

/**
 * hash-wasm compiles embedded base64 wasm at runtime
 * (WebAssembly.compile — forbidden on workerd). Patch its dist entries to
 * seed the per-algorithm module cache with statically-bound modules that
 * worker.ts injects via globalThis.__OT_HASH_WASM_MODULES__ (keyed by
 * hash-wasm's binary name, e.g. "argon2"). Only the algorithms we actually
 * use are injected; everything else keeps the original path on Node/Bun.
 */
const HASH_WASM_ANCHOR = `          if (!wasmModuleCache.has(binary.name)) {
              const asm = decodeBase64(binary.data);
              const promise = WebAssembly.compile(asm);
              wasmModuleCache.set(binary.name, promise);
          }`;
const HASH_WASM_REPLACEMENT = `          if (!wasmModuleCache.has(binary.name)) {
              // Patched by scripts/patch-prisma-wasm.ts (workerd): use the
              // statically-bound wasm modules injected by worker.ts instead
              // of compiling base64 bytes at runtime.
              const injected = globalThis.__OT_HASH_WASM_MODULES__;
              if (injected && injected[binary.name]) {
                  wasmModuleCache.set(binary.name, Promise.resolve(injected[binary.name]));
              } else {
                  const asm = decodeBase64(binary.data);
                  const promise = WebAssembly.compile(asm);
                  wasmModuleCache.set(binary.name, promise);
              }
          }`;

const HASH_WASM_FILES = [
  'node_modules/hash-wasm/dist/index.esm.js',
  'node_modules/hash-wasm/dist/index.umd.js',
].map((relative) => path.join(process.cwd(), relative));

for (const hashWasmFile of HASH_WASM_FILES) {
  let hashWasmSource: string;
  try {
    hashWasmSource = readFileSync(hashWasmFile, 'utf8');
  } catch (error) {
    console.error(`cannot read ${hashWasmFile}: ${error}`);
    process.exit(1);
  }

  if (hashWasmSource.includes('__OT_HASH_WASM_MODULES__')) {
    console.log(
      `${path.relative(process.cwd(), hashWasmFile)} already patched — nothing to do`,
    );
    continue;
  }
  // The anchor's exact indentation can drift between formats; fall back to a
  // looser match that still pins the compile call inside the cache check.
  const patched = hashWasmSource.includes(HASH_WASM_ANCHOR)
    ? hashWasmSource.replace(HASH_WASM_ANCHOR, HASH_WASM_REPLACEMENT)
    : hashWasmSource.replace(
        /if \(!wasmModuleCache\.has\(binary\.name\)\) \{\s*const asm = decodeBase64\(binary\.data\);\s*const promise = WebAssembly\.compile\(asm\);\s*wasmModuleCache\.set\(binary\.name, promise\);\s*\}/,
        HASH_WASM_REPLACEMENT
          .split('\n')
          .slice(1, -1)
          .map((line) => line.trim())
          .join('\n')
          .replace('__OT_HASH_WASM_MODULES__', '__OT_HASH_WASM_MODULES__'),
      );
  if (patched === hashWasmSource) {
    console.error(
      `expected wasm cache shape not found in ${path.relative(process.cwd(), hashWasmFile)} — hash-wasm version changed; update scripts/patch-prisma-wasm.ts`,
    );
    process.exit(1);
  }
  writeFileSync(hashWasmFile, patched);
  console.log(`patched ${path.relative(process.cwd(), hashWasmFile)}`);
}
